import os
import re
import subprocess
from pathlib import Path
from typing import Optional, Tuple

from app.config import CACHE_PATH, RESOURCE_PATH

from .logger import setup_logger
from .ass_auto_wrap import auto_wrap_ass_file
from .ass_effects import effect_text_layers
from .video_utils import get_video_info

logger = setup_logger("subtitle_preview")

SCRIPT_INFO_TEMPLATE = """[Script Info]
; Script generated by VideoSubtitleEditor
; https://github.com/WEIFENG2333
ScriptType: v4.00+
WrapStyle: 2
PlayResX: {video_width}
PlayResY: {video_height}


{style_str}

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
{dialogue}
"""

ASS_TEMP_FILENAME = CACHE_PATH / "preview.ass"  # 预览的临时 ASS 文件路径
PREVIEW_IMAGE_FILENAME = CACHE_PATH / "preview.png"  # 预览的图片路径
DEFAULT_BG_PATH = RESOURCE_PATH / "assets" / "default_bg.png"


def run_subprocess(command: list):
    """运行子进程命令，并处理异常"""
    try:
        subprocess.run(
            command,
            check=True,
            capture_output=True,
            creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0,
        )
    except subprocess.CalledProcessError as e:
        logger.error(f"Subprocess error: {e.stderr}")


def generate_ass_file(
    style_str: str,
    preview_text: Tuple[str, Optional[str]],
    video_width: int = 1280,
    video_height: int = 720,
) -> str:
    """生成临时 ASS 文件。

    The exported ASS produced by ASRData uses a 1280x720 script canvas.  Keep
    the preview on that same canvas even for portrait backgrounds, otherwise
    font, outline and shadow values look different between preview and export.
    """
    canvas = re.search(r"^; VideoCaptionerScriptCanvas:\s*(\d+),\s*(\d+)\s*$", style_str, re.MULTILINE)
    script_width, script_height = tuple(map(int, canvas.groups())) if canvas else (1280, 720)
    original_text, translate_text = preview_text

    dialogue = []
    preview_events = [("Default", original_text)]
    if translate_text:
        preview_events.insert(0, ("Secondary", translate_text))
    for style_name, text in preview_events:
        for layer, effect_text in effect_text_layers(style_str, style_name, text):
            dialogue.append(
                f"Dialogue: {layer},0:00:00.00,0:00:01.00,{style_name},,0,0,0,,{effect_text}"
            )

    ass_content = SCRIPT_INFO_TEMPLATE.format(
        style_str=style_str,
        dialogue=os.linesep.join(dialogue),
        video_width=script_width,
        video_height=script_height,
    )
    ASS_TEMP_FILENAME.parent.mkdir(parents=True, exist_ok=True)
    ASS_TEMP_FILENAME.write_text(ass_content, encoding="utf-8")
    return str(ASS_TEMP_FILENAME)


def ensure_background(bg_path: Path) -> Path:
    """确保背景图片存在，若不存在则创建默认黑色背景"""
    if not bg_path.is_file() or not bg_path.exists():
        if not Path(DEFAULT_BG_PATH).exists():
            DEFAULT_BG_PATH.parent.mkdir(parents=True, exist_ok=True)
            run_subprocess(
                [
                    "ffmpeg",
                    "-f",
                    "lavfi",
                    "-i",
                    "color=c=black:s=1920x1080",
                    "-frames:v",
                    "1",
                    str(DEFAULT_BG_PATH),
                ]
            )
        return Path(DEFAULT_BG_PATH)
    return bg_path


def generate_preview(
    style_str: str,
    preview_text: Tuple[str, Optional[str]],
    bg_path: str,
    width: int,
    height: int,
) -> str:
    """生成预览图片"""

    ass_file = generate_ass_file(style_str, preview_text, width, height)
    ass_file = auto_wrap_ass_file(ass_file)
    bg_path = ensure_background(Path(bg_path))

    output_path = PREVIEW_IMAGE_FILENAME
    output_path.parent.mkdir(parents=True, exist_ok=True)

    ass_file_processed = ass_file.replace("\\", "/").replace(":", r"\:")
    fonts_dir_processed = str(RESOURCE_PATH / "fonts").replace("\\", "/").replace(
        ":", r"\:"
    )
    render_width = int(round(int(width) * 1.5))
    render_height = int(round(int(height) * 1.5))
    transparent_canvas = (
        f"color=c=black@0.0:s={render_width}x{render_height}:"
        "d=1:r=1,format=rgba"
    )
    ass_filter = 'ass' if '; VideoCaptionerOriginalLanguage: ar' in style_str else 'subtitles'
    filter_complex = (
        f"[0:v]scale={int(width)}:{int(height)}:flags=lanczos[background];"
        "[1:v]"
        f"{ass_filter}='{ass_file_processed}':fontsdir='{fonts_dir_processed}':alpha=1,"
        f"scale={int(width)}:{int(height)}:flags=lanczos[subtitles_v9];"
        "[background][subtitles_v9]"
        "overlay=shortest=1:format=auto[preview_v9]"
    )
    cmd = [
        "ffmpeg",
        "-y",
        "-i",
        str(bg_path),
        "-f",
        "lavfi",
        "-i",
        transparent_canvas,
        "-filter_complex",
        filter_complex,
        "-map",
        "[preview_v9]",
        "-frames:v",
        "1",
        str(output_path),
    ]
    run_subprocess(cmd)
    return str(output_path)


